var payload = msg.payload;
if (typeof payload === 'string') { payload = JSON.parse(payload); }

var hexStr = payload.data;
if (!hexStr || hexStr.length < 28) { return null; }

var buf = Buffer.from(hexStr, 'hex');

var lat = buf.readInt32BE(0) / 1e6;
var lon = buf.readInt32BE(4) / 1e6;
var vel = buf.readUInt8(10);
var sat = buf.readUInt8(11);
var fix = buf.readUInt8(12);
var temp = buf.readUInt8(13);
var hum = buf.readUInt8(14);

// Descodifica os pontos da cerca (bytes 15-46)
var cercaObj = {};
if (buf.length >= 47) {
    var cercaDigital = [];
    for (var i = 0; i < 4; i++) {
        var offset = 15 + i * 8;
        var cLat = buf.readInt32BE(offset) / 1e6;
        var cLon = buf.readInt32BE(offset + 4) / 1e6;
        cercaDigital.push({ lat: cLat, lon: cLon });
        cercaObj["cerca_lat_" + i] = cLat;
        cercaObj["cerca_lon_" + i] = cLon;
    }
    global.set('cercaDigital', cercaDigital);
    node.warn("Cerca sincronizada: " + JSON.stringify(cercaDigital[0]));
}

// Descodifica a distância (bytes 47-48)
var distancia = 0;
if (buf.length >= 49) {
    distancia = buf.readUInt16BE(47);
    node.warn("Distância: " + distancia + "m");
}

// Saída 1 → Geofencing Ray Casting
var msgGeofence = {
    payload: {
        lat: lat,
        lon: lon,
        temperatura: temp,
        humidade: hum
    }
};

// Saída 2 → InfluxDB
var msgInflux = {
    payload: {
        latitude: lat,
        longitude: lon,
        satelites: sat,
        fix: fix,
        temperatura: temp,
        humidade: hum,
        distancia: distancia,
        ...cercaObj
    },
    measurement: "animal"
};

return [msgGeofence, msgInflux];

// 1. Lê coordenadas
var lat, lon;
if (msg.payload && typeof msg.payload.lat !== 'undefined') {
    lat = msg.payload.lat;
    lon = msg.payload.lon;
} else {
    node.warn("Estrutura desconhecida: " + JSON.stringify(msg.payload));
    return null;
}

// 2. Recupera a cerca
var cerca = global.get('cercaDigital') || [];
if (!cerca || cerca.length < 3) {
    node.warn("Nenhuma cerca definida!");
    return [{ payload: { name: "Coleira", lat: lat, lon: lon } }, null, null];
}

// Ray Casting
function verificarRayCasting(lat, lon, poligono) {
    var dentro = false;
    for (var i = 0, j = poligono.length - 1; i < poligono.length; j = i++) {
        var xi = poligono[i].lat, yi = poligono[i].lon;
        var xj = poligono[j].lat, yj = poligono[j].lon;
        var intersect = ((yi > lon) !== (yj > lon)) &&
            (lat < (xj - xi) * (lon - yi) / (yj - yi) + xi);
        if (intersect) dentro = !dentro;
    }
    return dentro;
}

// Distância
function distanciaAoLimite(lat, lon, poligono) {
    var R = 6371000;
    var distMin = Infinity;
    for (var i = 0; i < poligono.length; i++) {
        var dLat = (lat - poligono[i].lat) * Math.PI / 180;
        var dLon = (lon - poligono[i].lon) * Math.PI / 180;
        var a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat * Math.PI / 180) * Math.cos(poligono[i].lat * Math.PI / 180) *
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
        var dist = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        if (dist < distMin) distMin = dist;
    }
    return distMin;
}

var dentro = verificarRayCasting(lat, lon, cerca);
var distancia = distanciaAoLimite(lat, lon, cerca);
var ZONA_AVISO = 15;

var estado;
if (!dentro) { estado = 2; }
else if (distancia <= ZONA_AVISO) { estado = 1; }
else { estado = 0; }

// CORRECTO — parênteses correctos
node.warn((estado === 0 ? "SEGURO" : estado === 1 ? "AVISO" : "FUGA") +
    " | Distância: " + distancia.toFixed(1) + "m");

// Marcador para o Worldmap
var msgMapa = {
    payload: {
        name: "Coleira",
        lat: lat,
        lon: lon
    }
};


// InfluxDB — agora inclui latitude e longitude também
var msgEstado = {
    payload: {
        latitude:     lat,
        longitude:    lon,
        estado_cerca: estado,
        distancia:    parseFloat(distancia.toFixed(1))
    },
    measurement: "animal"
};


// Saída 1 → Worldmap
// Saída 2 → InfluxDB
return [msgMapa, msgEstado];

node.warn("Evento recebido: " + JSON.stringify(msg.payload)); 

var payload = msg.payload; 

if (payload && payload.action === "draw" &&  
    payload.type && payload.type.toLowerCase() === "polygon") { 

    var pontos = payload.points || payload.area || []; 

    node.warn("Pontos recebidos: " + JSON.stringify(pontos)); 

    if (pontos && pontos.length >= 3) { 

        // Converte lng → lon para compatibilidade com o Geofencing 
        var pontosConvertidos = pontos.map(function(p) { 
            return { lat: p.lat, lon: p.lng || p.lon }; 
        }); 

        // Guarda no contexto global para o Ray Casting ler em tempo real 
        global.set('cercaDigital', pontosConvertidos); 
        node.warn('Cerca guardada com ' + pontosConvertidos.length + ' pontos na memória!'); 

        // ==========================================  
        //  BLOCO DO INFLUXDB CORRIGIDO E ESTRUTURADO 
        // ==========================================  
        var msgInflux = {   
            measurement: "animal",
            // Passamos um array onde cada elemento segue rigorosamente o formato do nó node-red-contrib-influxdb
            payload: pontosConvertidos.map(function(p, i) {    
                return [
                    {
                        // Campos (Fields): Valores numéricos para plotar no mapa
                        cerca_lat: p.lat,    
                        cerca_lon: p.lon,
                        ordem:     i
                    },
                    {
                        // Tags: Metadados para filtrar tudo de uma só vez com facilidade
                        cerca_id: "cerca_principal",
                        tipo_dado: "perimetro"
                    }
                ];   
            })
        };

        // Notificação visual para o mapa (Worldmap Toast)  
        var msgMapaToast = {  
            payload: {  
                command: {  
                    toast: {  
                        title: "Cerca Actualizada",  
                        text: "Cerca guardada com " + pontosConvertidos.length + " pontos!",  
                        status: "success"  
                    }  
                }  
            }  
        };  

        // RETURN: Saída 1 (Toast) e Saída 2 (InfluxDB)
        return [msgMapaToast, msgInflux]; 
    } 
} 

// Se não entrar nas condições acima, não envia nada e evita erros no flow
return null;
